def load(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))

def table(headers, rows):
    return '\n'.join(['| ' + ' | '.join(headers) + ' |', '| ' + ' | '.join(('---' for _ in headers)) + ' |'] + ['| ' + ' | '.join((str(item) for item in row)) + ' |' for row in rows])

def report_write(path, title, sections, intro=''):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    links = '\n'.join((f'- [{heading}](#section-{index})' for index, (heading, _) in enumerate(sections, 1)))
    content = f'# {title}\n\n{intro}\n\n<a id="report-toc"></a>\n\n## 目录\n\n{links}\n'
    for index, (heading, body) in enumerate(sections, 1):
        content += f'\n<a id="section-{index}"></a>\n\n## {heading}\n\n{body}\n\n[返回目录](#report-toc)\n'
    Path(path).write_text(content, encoding='utf-8')
    LAYOUT.normalize_document(Path(path))

